"""Save the actual first search hit's bounded public-source research, no API call."""
import json

from backend.app.assessments import load_reference_material
from backend.app.models import Evidence
from backend.app.research_ingest import accept_research
from backend.app.settings import APP_ROOT, Settings
from backend.app.state import StateService


def run():
    folder=APP_ROOT/'backend/work/first-scout'
    out=folder/'research.json'
    if out.exists():print(out.read_text());return
    search=json.loads((folder/'search.json').read_text());case_id=search['case_id']
    settings=Settings.from_environment();ref=load_reference_material(APP_ROOT,settings.reference_source_config)
    state=StateService(settings.sqlite_path(),ref);state.initialize();case=state.detail(case_id)
    receipts={r['name']:r for r in json.loads((folder/'sources/receipts.json').read_text())}
    person='person:nurture:sabina-ben-kasim';role='role:nurture:sabina-founder-ceo';company=case.company_id
    observations=[];subjects={};metadata=[]
    def observation(key,source,claim,summary,kind='company',subject=None,publication=None,assertion='source_reported'):
        r=receipts[source]
        if r['http_status']!=200 and assertion!='observed':raise ValueError('Do not import inaccessible source text as live observation')
        eid='evidence:nurture:'+key
        observations.append(Evidence(id=eid,company_id=company,claim_type=claim,summary=summary,source_url=r['url'],source_key='public-source:'+r['sha256']+':'+key,observed_at=None,retrieved_at=r['retrieved_at'],data_mode='live'))
        subjects[eid]={'kind':kind,'id':subject or company}
        metadata.append({'evidence_id':eid,'original_source_id':'source:nurture:'+source,'assertion_kind':assertion,'support_status':'supported' if assertion=='observed' else 'unknown','source_type':'public_source_access_attempt' if assertion=='observed' else ('publisher_profile_press_release' if source=='recognition-release' else 'first_party_company_page'),'source_quality':'access_status_only' if assertion=='observed' else 'attributable_report_not_independent_verification','publication_time':{'precision':'day','value':publication,'basis':'publication'} if publication else {'precision':'unknown'},'limitations':['Live retrieval does not independently verify the claim. Company pages share an interested owner; the recognition release is publisher-provided promotional material.','Publication/retrieval dates do not establish employment tenure or founding dates.']})
        return eid
    identity=observation('identity','about','brand_legal_entity_link','The company-controlled about page presents Nurture Bridge AI Consults and identifies its frameworks as proprietary to Nurture Bridge Marketing, LLC in the footer. This supports the operating-brand/domain link; no independent corporate registry check was performed.')
    founding=observation('founder-role','about','source_reported_founder_ceo','The company about page names Sabina Ben Kasim as Founder and CEO of Nurture Bridge AI Consults. Current tenure dates, other founders, and independently verified ownership are not supplied.','relationship',role)
    background=observation('founder-background','about','source_reported_work_background','The founder describes more than two decades across clinical care, utilization management, care coordination and healthcare operations. This is attributable first-person background, not independently verified work chronology or a pedigree score.','person',person)
    methods=observation('founder-methods','about','source_reported_methodology_contribution','The company attributes creation of Workflow-to-Value and Referral Reliability Bridge methodologies to Sabina Ben Kasim. No working software, measured execution history or independent authorship verification was inspected.','person',person)
    offering=observation('current-offering','services','current_services_not_proprietary_platform','The current services page explicitly describes consulting and advisory engagements and says it does not sell a proprietary AI software platform. Available work covers assessment, workflow optimization, governance and implementation support. A reusable differentiated product/asset is not demonstrated by these service descriptions.')
    roadmap=observation('future-services','services','unavailable_future_capabilities','The services page labels workforce education and ongoing monitoring/reassessment as in development and not currently offered. These are service capabilities; no inference of a promised software launch, customer adoption or recurring revenue is made.')
    problem=observation('problem-context','home','first_party_workflow_problem','The live company site focuses on healthcare operational systems and referral reliability. This supplies a track-H problem/user lead, not independent demand, ROI, product performance or customer deployment evidence.')
    recognition=observation('recognition-publication','recognition-release','dated_recognition_publication','A publisher-provided release dated 21 November 2025 profiles Sabina Ben Kasim as founder/CEO of Nurture Bridge Marketing and discusses its homecare services. This is a dated publication, not the founding date or an independently verified operational milestone.',publication='2025-11-21')
    prior=observation('prior-organisations','recognition-release','reported_prior_organisations','The promotional profile reports prior roles at Johns Hopkins Health Care and Signify Health. Role titles, dates, responsibilities and tenure have not been independently established; no relationship or performance inference beyond the report is made.','person',person,publication='2025-11-21')
    access=observation('case-study-access','case-studies','source_access_failure','Direct retrieval of the linked case-studies page returned HTTP 404 on 24 October 2026. This records an access failure only; it does not prove that customers, studies or product evidence do not exist.',assertion='observed')
    entities=[{'id':'project:nurture:workflow-to-value','kind':'project','label':'Workflow-to-Value methodology','evidence_ids':[methods],'attributes':{'commercial_form':'Consulting methodology; software/product proof unknown'}},{'id':'project:nurture:referral-reliability','kind':'project','label':'Referral Reliability Bridge','evidence_ids':[methods,offering],'attributes':{'artifact_inspected':False,'product_gate':'unknown'}},{'id':'org:reported:johns-hopkins-health-care','kind':'organisation','label':'Johns Hopkins Health Care (reported prior role)','evidence_ids':[prior]},{'id':'org:reported:signify-health','kind':'organisation','label':'Signify Health (reported prior role)','evidence_ids':[prior]},{'id':'event:nurture:2025-recognition-publication','kind':'event','label':'2025 founder-profile publication','evidence_ids':[recognition],'temporal_scope':{'precision':'day','value':'2025-11-21','basis':'publication','limitation':'Publication date; recognition event/founding date not separately established'}}]
    assertions=[]
    def edge(id,start,end,relation,label,eids,limitation):assertions.append({'id':id,'from_id':start,'to_id':end,'relation':relation,'label':label,'evidence_ids':eids,'assertion_kind':'source_reported','support_status':'unknown','limitation':limitation})
    edge('edge:nurture:created-method',person,'project:nurture:workflow-to-value','worked_on','Company reports creator role',[methods],'Attribution is company-reported; actual work and repeatable product were not inspected.')
    edge('edge:nurture:offers-method',company,'project:nurture:referral-reliability','offers','Describes a services framework',[methods,offering],'A consulting framework is not automatically a reusable software product or differentiated asset.')
    edge('edge:nurture:prior-jhh',person,'org:reported:johns-hopkins-health-care','held_role_at','Publisher reports prior role',[prior],'No title, dates, tenure or independently verified contribution is established.')
    edge('edge:nurture:prior-signify',person,'org:reported:signify-health','held_role_at','Publisher reports prior role',[prior],'No title, dates, tenure or independently verified contribution is established.')
    edge('edge:nurture:recognition', 'event:nurture:2025-recognition-publication',person,'concerns','Published founder profile',[recognition],'Promotional recognition publication is not product validation or a personality/qualification gate.')
    questions=[{'id':'question:nurture:reusable-core','target_node_ids':[company,'project:nurture:referral-reliability'],'criterion_ids':['C4','C7'],'question':'Is there a repeatable differentiated product or asset beyond advisory engagements, and what inspectable worked artifact demonstrates it?','decision_consequence':'A sourced reusable core could justify renewed investigation; services descriptions alone do not establish the selected review gate.'},{'id':'question:nurture:team-history','target_node_ids':[person,company],'criterion_ids':['C2'],'question':'What current role-tenure and attributable work evidence verifies the founder account, and is there a wider founding team?','decision_consequence':'Resolve team/problem attribution without inventing cofounders, relationships or a pedigree score.'},{'id':'question:nurture:novelty','target_node_ids':[company],'question':'What authoritative known-company/YC record establishes backing or declared-universe novelty?','decision_consequence':'Backing and novelty remain unknown; do not count the lead as a novel YC opportunity.'},{'id':'question:nurture:why-now','target_node_ids':[company],'criterion_ids':['C8'],'question':'Is there a dated product or experimental milestone that warrants action now, beyond the 2025 publicity?','decision_consequence':'Choose a concrete future reopening trigger rather than inventing current momentum.'}]
    packet={'people':[{'id':person,'name':'Sabina Ben Kasim'}],'relationships':[{'id':role,'person_id':person,'company_id':company,'role':'Founder/CEO (company-reported; tenure unverified)','status':'supported','evidence_ids':[founding]}],'subjects':subjects,'observation_metadata':metadata,'entities':entities,'assertions':assertions,'questions':questions,'source_fetch_receipts':list(receipts.values()),'limitations':['People API access was not tested; identities/roles come from explicitly attributable public pages.','Current service-page text differs from older cached marketing copy; current direct-fetch observations are retained with dates.','No working product, customer study, clinical validation, known-YC backing or independent founder history was verified.']}
    packet_id=accept_research(state,case_id,observations,packet,expected_case_version=case.version)
    result={'case_id':case_id,'research_packet_id':packet_id,'new_observations':len(observations),'people':1,'reported_roles':1,'extra_entities':len(entities),'provider_people_calls':0,'sources_directly_fetched':len(receipts),'mode':'live_retrieval_source_reported_claims','qualification_policy_active':False}
    out.write_text(json.dumps(result,indent=2));print(json.dumps(result))


if __name__=='__main__':run()
